'use client';

import { useRef, type CSSProperties, type KeyboardEvent } from 'react';
import './segmented-switch.css';

export interface SegmentedSwitchProps {
  options: { value: string; label: string }[];
  value: string;
  onChange: (value: string) => void;
  /** Accessible name for the group. */
  label: string;
  className?: string;
}

/** A radio group whose thumb slides to the chosen option. */
export function SegmentedSwitch({
  options,
  value,
  onChange,
  label,
  className = '',
}: SegmentedSwitchProps) {
  const group = useRef<HTMLDivElement>(null);
  const index = Math.max(
    0,
    options.findIndex((option) => option.value === value)
  );

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const step =
      event.key === 'ArrowRight' || event.key === 'ArrowDown'
        ? 1
        : event.key === 'ArrowLeft' || event.key === 'ArrowUp'
          ? -1
          : 0;
    if (!step) return;
    event.preventDefault();
    const next = options[(index + step + options.length) % options.length];
    onChange(next.value);
    group.current
      ?.querySelector<HTMLElement>(`[data-value="${next.value}"]`)
      ?.focus();
  };

  return (
    <div
      ref={group}
      role='radiogroup'
      aria-label={label}
      className={`mg-segmented ${className}`}
      style={
        { '--mg-count': options.length, '--mg-index': index } as CSSProperties
      }
      onKeyDown={onKeyDown}
    >
      <span className='mg-segmented__thumb' aria-hidden='true' />
      {options.map((option) => (
        <button
          key={option.value}
          type='button'
          role='radio'
          data-value={option.value}
          aria-checked={option.value === value}
          tabIndex={option.value === value ? 0 : -1}
          className='mg-segmented__option'
          onClick={() => onChange(option.value)}
        >
          {option.label}
        </button>
      ))}
    </div>
  );
}

.mg-segmented {
  position: relative;
  display: inline-grid;
  grid-template-columns: repeat(var(--mg-count), minmax(0, 1fr));
  padding: 4px;
  border: 1px solid var(--mg-line, #303030);
  border-radius: 12px;
  background: var(--mg-raised, #1b1b1b);
}

.mg-segmented__thumb {
  position: absolute;
  top: 4px;
  bottom: 4px;
  left: 4px;
  width: calc((100% - 8px) / var(--mg-count));
  border-radius: 8px;
  background: var(--mg-accent, #eaf2fb);
  transform: translateX(calc(var(--mg-index) * 100%));
  transition: transform 300ms cubic-bezier(0.3, 1.2, 0.4, 1);
}

.mg-segmented__option {
  position: relative;
  min-height: 44px;
  padding: 0 18px;
  border: 0;
  border-radius: 8px;
  background: none;
  color: #b8b8b8;
  font: inherit;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  transition: color 200ms ease;
}

.mg-segmented__option[aria-checked='true'] {
  color: #fff;
}

.mg-segmented__option:focus-visible {
  outline: 2px solid var(--mg-text, #ffffff);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  .mg-segmented__thumb {
    transition: none;
  }
}
